      SUBROUTINE DEPICTCC     CHARACTERIZES ELEMENT AS TO WHETHER IT IS AN OPERATION,C     OR A PHYSICAL ELEMENT THAT CAN BE ROTATED, OR IS COMPOUNDCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM0F.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'ELM38A.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'INDBND.CIN'CC     LOCAL VARIABLESC      INTEGER         IDATA, IDL1, IDL2, IPT, NMARKT, RORC, TYT      EXTERNAL        IDATACC----------------------------------------------------------------------C      ATWE = ATWORK      OPER = .FALSE.      RABL = .FALSE.      WFRN = .FALSE.      NTILT = 0C      IF (TYPE .GE. 82 .AND. TYPE .LE. 86) GO TO 5200      GO TO ( 100, 200, 300, 400, 500, 600, 700, 800, 900,1000,     1       1100,1200,1300,1400,1500,1600,1700,1800,1900,2000,     2       2100,2200,2300,2400,2500,2600,2700,2800,2800,3000,     3       3100,3200,3300,3400,3500,3500,3700,3800,3900,4000,     4       4100,4200,4300,4400,4500,4600,4600,4600), TYPEC  100 ATWE = .NOT. MKG      GO TO 5200C  200 ATWE = ATWE .AND. .NOT. MKG      RABL = .TRUE.      GO TO 5200C  300 ATWE = ATWE .AND. .NOT. MKG      GO TO 5200C  400 ATWE = ATWE .AND. .NOT. MKG      RABL = .TRUE.      NTILT = 18      GO TO 5200C  500 ATWE = ATWE .AND. .NOT. MKG      RABL = .TRUE.      NTILT = 6      GO TO 5200C  600 OPER = .TRUE.      ATWE = .FALSE.      IF (MKG) THEN        IF (IPTOJ(3) .NE. 0) THEN          NMARKT = IDATA(I+3)          ATWE = NMARKS .EQ. NMARKT        ENDIF      ELSE                IF (IPTOJ(3) .EQ. 0) ATWE = .TRUE.      ENDIF      GO TO 5200C  700 IDL1 = IDATA(ISTOR(NUM-1))      IF (IDL1 .EQ. 1) THEN        ATWE = .NOT. MKG      ELSE          IDL2 = IDATA(ISTOR(NUM-2))        IF (IDL1 .EQ. 12 .AND. IDL2 .EQ. 1) THEN          ATWE = .NOT. MKG        ENDIF      ENDIF      GO TO 5200C  800 TYT = INT(DATA(I+7))      RORC = MOD(TYT,10)      ATWE = .FALSE.      IF (RORC .GE. 3) THEN        ATWE = (.NOT. MKG .AND. IPTOJ(9) .EQ. 0)     1         .OR. (MKG .AND. IPTOJ(9) .NE. 0)      ELSE        IF (MKG) THEN          IF (IPTOJ(9) .NE. 0 .AND. TIE(I+9) .EQ. 101) THEN            NMARKT = IDATA(I+9)            ATWE = NMARKS .EQ. NMARKT          ENDIF        ELSE IF (ALGR) THEN          IF (IPTOJ(9) .NE. 0 .AND. TIE(I+9) .EQ. 102) THEN            ATWE = IDATA(I+9) .EQ. NMARK          ENDIF          ELSE          IF (ATWORK) THEN            IF (IPTOJ(9) .EQ. 0) ATWE = .TRUE.          ENDIF        ENDIF      ENDIF      OPER = IDATA(I+9) .GE. 1 .AND. TIE(I+9) .EQ. 100      GO TO 5200C  900 ATWE = ATWE .AND. .NOT. MKG      GO TO 5200C 1000 OPER = .TRUE.      ATWE = .FALSE.      IPT = IPTOJ(7)      IF (MKG) THEN        IF (IPT .NE. 0) THEN          NMARKT = IDATA(I+IPT)          ATWE = NMARKS .EQ. NMARKT        ENDIF      ELSE        ATWE = IPTOJ(7) .EQ. 0       ENDIF      GO TO 5200C 1100 ATWE = ATWE .AND. .NOT. MKG      GO TO 5200C 1200 ATWE = .NOT. MKG      GO TO 5200C 1300 OPER = .TRUE.      IF (MKG) THEN        IF (IPTOJ(2) .NE. 0) THEN          NMARKT = IDATA(I+2)          ATWE = NMARKS .EQ. NMARKT        ELSE          ATWE = .FALSE.        ENDIF      ELSE        ATWE = IPTOJ(2) .EQ. 0       ENDIF      GO TO 5200C 1400 ATWE = ATWE .AND. .NOT. MKG      GO TO 5200C 1500 ATWE = .TRUE.      GO TO 5200C 1600 ATWE = .NOT. MKG      GO TO 5200C 1700 ATWE = .NOT. MKG      GO TO 5200C 1800 ATWE = ATWE .AND. .NOT. MKG      RABL = .TRUE.      NTILT = 5      GO TO 5200C 1900 ATWE = ATWE .AND. .NOT. MKG      GO TO 5200C 2000 ATWE = ATWE .AND. .NOT. MKG      GO TO 5200C 2100 GO TO 5200C 2200 ATWE = ATWE .OR. PLNOW      OPER = .TRUE.      GO TO 5200C 2300 ATWE = ATWE .OR. .NOT. MKG      OPER = .TRUE.      GO TO 5200C 2400 ATWE = .NOT. MKG      GO TO 5200C 2500 ATWE = ATWE .AND. .NOT. MKG      RABL = .TRUE.      NTILT = 5      GO TO 5200C 2600 ATWE = .NOT. MKG      GO TO 5200C 2700 ATWE = .NOT. MKG      GO TO 5200C 2800 ATWE = ATWE .AND. .NOT. MKG      RABL = .TRUE.      WFRN = .TRUE.      NTILT = 24      GO TO 5200C 3000 ATWE = .NOT. MKG      GO TO 5200C 3100 ATWE = ATWE .AND. .NOT. MKG      GO TO 5200C 3200 GO TO 5200C 3300 OPER = .TRUE.      ATWE = .FALSE.      IF (MKG) THEN        IF (IPTOJ(2) .NE. 0) THEN          NMARKT = IDATA(I+2)          ATWE = NMARKS .EQ. NMARKT        ENDIF      ELSE        IF (IPTOJ(2) .EQ. 0) ATWE = .TRUE.      ENDIF      GO TO 5200C 3400 ATWE = ATWE .AND. .NOT. MKG      GO TO 5200C 3500 ATWE = ATWE .AND. .NOT. MKG      RABL = .TRUE.      WFRN = .TRUE.      NTILT = 5      GO TO 5200C 3700 OPER = .TRUE.      ATWE = .FALSE.      IF (MKG) THEN        IF (IPTOJ(3) .NE. 0) THEN          NMARKT = IDATA(I+3)          ATWE = NMARKS .EQ. NMARKT        ENDIF      ELSE        IF (IPTOJ(3) .EQ. 0) ATWE = .TRUE.      ENDIF      GO TO 5200C 3800 ATWE = .NOT. MKG      GO TO 5200C 3900 ATWE = .NOT. MKG      GO TO 5200C 4000 ATWE = ATWE .AND. .NOT. MKG      GO TO 5200C 4100 ATWE = ATWE .AND. .NOT. MKG      RABL = .TRUE.      NTILT = 10      GO TO 5200C 4200 ATWE = ATWE .AND. .NOT. MKG      RABL = .TRUE.      WFRN = .TRUE.      GO TO 5200C 4300 IDL1 = IDATA(ISTOR(NUM-1))      IF (IDL1 .EQ. 1) THEN        ATWE = .TRUE.      ELSE          IDL2 = IDATA(ISTOR(NUM-2))        IF (IDL1 .EQ. 12 .AND. IDL2 .EQ. 1) THEN          ATWE = .TRUE.        ENDIF      ENDIF      GO TO 5200C 4400 ATWE = .TRUE.      GO TO 5200C 4500 ATWE = ATWE .AND. .NOT. MKG      GO TO 5200C 4600 ATWE = ATWE .AND. .NOT. MKG      GO TO 5200C 5200 RETURN      END